"""Partial2/3s extension of the shared grace comparison."""
import json
from pathlib import Path
from experiments.analysis.summarize_grace_partial import OUT,FOLDERS

def status_table(table,metric):
 rows=[['V9 best','0,5 s','Punkt odniesienia','98,75%'],['V10 grace1s','1 s','Trening zakończony:30,02 mln',f"{100*metric['eval/worst_height_success_rate']:.2f}%"]]
 for g in [2,3]:
  m=json.loads((FOLDERS[g]/'checkpoints.json').read_text())['best']['metrics'];rows.append([f'V10 grace{g}s',f'{g} s','Wstępny model:8,39 mln',f"{100*m['eval/worst_height_success_rate']:.2f}%"])
 return table(['Wariant','Kara od pierwszego kontaktu','Stan modelu','Worst-height: średnia w paśmie3–4 m/s'],rows)

def build(table):
 s=json.loads((OUT/'summary.json').read_text());result='<h3>Uzupełnienie: wstępne modele 2 s i 3 s po kilku godzinach</h3><p>To snapshoty trwających treningów. Modele pochodzą z pierwszej ewaluacji przy 8 388 608 przejściach. Log 2 s dochodzi do 10 616 832, a 3 s do 10 747 904 przejść, lecz nowszych wag nie ma w pobranych checkpointach. Best i latest w każdym wariancie są identyczne. W logach nie ma Traceback/OOM/NaN. Dla porównania pobrany model1 s zakończył30 015 488 nowych przejść, więc odtworzenia nie mają równego budżetu.</p>'
 result+=table(['Warunki','Wariant','Przejścia modelu','Sukcesy','Skuteczność','95% Wilson','Mediana kontakt→sukces [s]'],[[f"{g['height']:g} m / {g['speed']:g} m/s",f"{g['grace']} s",str(g['checkpoint_step']),f"{g['successes']}/{g['count']}",f"{100*g['rate']:.1f}%",f"{100*g['wilson95'][0]:.1f}–{100*g['wilson95'][1]:.1f}%",'—' if g['success_contact_to_end_median'] is None else f"{g['success_contact_to_end_median']:.3f}"] for g in s['groups']])
 result+='<p>Wykonano po 192 odtworzenia2 s i 3 s, na tych samych przypadkach co 1 s i v9. Potwierdzono hashe fizycznych stanów. Identycznych best/latest nie testowano dwukrotnie. To znany zestaw diagnostyczny, nie nowy held-out. Sukces przy 3 m/4 m/s ma różnicę dwóch prób między2 s i 3 s; nie wystarcza to do ogłoszenia przewagi metody.</p><h4>Porównanie przy równych 8,39 mln przejść</h4><p>Dla 1 s nie pobrano modelu z 8,39 mln, ale zachowała się jego siatka w logu. Poniższa tabela porównuje tę samą ewaluację klastra i ten sam budżet, zamiast zestawiać końcowe1 s z wczesnym2/3 s. Liczebności 1 s odtworzono z drukowanego logu;2/3 s pochodzą z metadanych checkpointu.</p>'
 rows=[]
 for h in [1.,1.5,2.,2.5,3.]:
  rows.append([f'{h:g} m']+[f"{next(c['successes'] for c in e['cells'] if c['controller']=='policy' and c['height']==h and c['speed']==4)}/64" for e in s['budget_aligned_grids']])
 result+=table(['Wysokość /4 m/s','1 s przy 8,39 mln','2 s przy 8,39 mln','3 s przy 8,39 mln'],rows)
 result+='<figure class="chart"><img src="../artifacts/'+OUT.name+'/comparison.png" alt="Odtworzenia różnych budżetów i walidacja przy równych budżetach"><figcaption>Lewo: sparowane przypadki obecnych modeli. Prawo: walidacja przy jednakowych8,39 mln przejść. Tych dwóch porównań nie należy mieszać.</figcaption></figure><h4>Czy dłuższe grace wywołuje dłuższą stabilizację?</h4>'
 result+=table(['Wariant','Udane próby3 m/4 m/s','Mediana drogi bazy po kontakcie [m]','Mediana przemieszczenia netto [m]'],[[f"{m['grace']} s",str(m['n']),f"{m['median_base_path_m']:.3f}",f"{m['median_base_net_m']:.3f}"] for m in s['motion']])
 result+='<p>Droga bazy w udanych próbach pozostaje około 0,40–0,42 m. To nie licznik kroków ani odbić: korpus może się przesuwać również przez ugięcie lub poślizg. Zestawy sukcesów różnią się nieco między modelami, a zapis trajektorii kończy się o jeden krok sterowania przed końcem epizodu. Mediany czasu kontakt→sukces nadal wynoszą około 2 s. Wszystkie udane odtworzenia 3 s kończą się przed włączeniem jego kary. W ostatniej agregacji logu koszt ruchu dla 3 s wynosi 0, a dla2 s jest bardzo mały (-3,73e-5). To nie dowód, że koszt nigdy nie wystąpił podczas treningu, ale pokazuje jego małą aktywność na obecnym etapie.</p><h4>Film2 s kontra 3 s</h4>'
 movie=json.loads((OUT/'videos.json').read_text())[0]
 result+=f'<figure><video controls preload="metadata" src="{movie["src"]}" poster="{movie["poster"]}"></video><figcaption>Lewo2 s, prawo3 s; modele8,39 mln. Pierwszy z góry ustalony przypadek3 m/4 m/s i pierwszy3 m/5 m/s, bez filtrowania po wyniku. Każdy wynik i czas końca potwierdzono osobnym replayem.4× wolniej, obraz zatrzymuje się po wyniku.</figcaption></figure>'
 result+='<h4>Opinia na tym etapie</h4><p>Widać utrzymanie opanowanego zakresu4 m/s i pewne różnice zależne od wysokości oraz kierunku. W równym budżecie2 s wygląda lepiej od 3 s na 1 m/4 m/s(63 wobec59 sukcesów); w odtworzeniach3 m/4 m/s 3 s ma64 wobec62. Nie ma jednej spójnej przewagi.5 m/s pozostaje nieopanowane. Wyniki nie pokazują jeszcze wydłużonej strategii stabilizacji ani większej drogi ruchu po kontakcie.</p><p>Ponieważ sukces może zakończyć epizod około 2 s po kontakcie, kara od 3 s w udanych próbach często nie ma możliwości zadziałać. Wariant 3 s staje się wtedy zbliżony do wyłączenia tej kary, a nie do wymuszenia trzech sekund stabilizowania. Nie zmieniamy jeszcze definicji zadania. Warto dokończyć treningi, zachować checkpointy przy równych krokach oraz pobrać cały landing_evaluation/. Końcowe wnioski wymagają nowych seedów ewaluacji i powtórzeń treningu.</p><p><a href="../artifacts/'+OUT.name+'/summary.json">Wszystkie zestawienia</a></p>'
 result+='<h4>Plan kolejnego kierunku: kroki hamujące</h4><p>Przygotowano osobny plan lądowanie → kroki hamujące → zatrzymanie. To projekt eksperymentu, bez zmian obecnych treningów.</p><p><a href="../article/stepping_energy_dissipation_plan.md">Analiza celu, curriculum, nagród i ewaluacji</a></p>'
 return result

def overview():
 return '<section id="aktualnie" class="stage"><div class="stage-label">Aktualny stan ·03.11.2026</div><h2>Grace2 s i 3 s: wstępne wyniki przy 8,39 mln przejść</h2><p>Przetestowano po 192 przypadki obu wariantów. Przy 3 m/4 m/s 2 s daje 62/64, a 3 s 64/64. Nie widać jeszcze dłuższego czasu stabilizacji. Modele1 s mają większy budżet 30 mln; raport zawiera także porównanie przy równych 8,39 mln. Treningi2/3 s nie są zakończone.</p><p><a href="#e22">Porównanie1/2/3 s i nowy film</a> · <a href="#branch-aerial">Obrót w powietrzu</a></p></section>'
